def p(text, kind='body'):
    return Paragraph(escape(text).replace('\n','<br/>'), styles[kind])

def h(text): return p(text, 'h')
def sub(text): return p(text, 'sub')
def bullet(text): return p('• ' + text)
def table(headers, rows, widths=None):
    data = [[p(t, 'headcell') for t in headers]] + [[p(str(t), 'cell') for t in row] for row in rows]
    t = Table(data, colWidths=widths or [510/len(headers)]*len(headers), hAlign='LEFT')
    t._wide = True
    t.setStyle(TableStyle([
        ('BACKGROUND',(0,0),(-1,0),BLUE), ('GRID',(0,0),(-1,-1),.45,colors.black),
        ('VALIGN',(0,0),(-1,-1),'TOP'), ('LEFTPADDING',(0,0),(-1,-1),5),
        ('RIGHTPADDING',(0,0),(-1,-1),5), ('TOPPADDING',(0,0),(-1,-1),5),
        ('BOTTOMPADDING',(0,0),(-1,-1),5),
    ]))
    return t

def requirement(code, title, status, priority, detail, business=False):
    if business:
        return table(['ID','Descrição','Requisitos relacionados'],[[code,title,status],['Detalhamento',detail,priority]], [60,305,145])
    return table(['ID','Descrição','Status','Prioridade'],[[code,title,status,priority],['Detalhamento',detail,'','']], [62,255,128,65])

def compact_requirements(items, business=False):
    # Cada requisito conserva seu código; o detalhamento ocupa a largura útil.
    result=[]
    for code,title,status,priority,detail in items:
        if business:
            rows=[[code,title,status],['Detalhamento: '+detail,'','']]
            t=table(['ID','Descrição','Requisitos relacionados'], rows, [60,315,135])
        else:
            rows=[[code,title,status,priority],['Detalhamento: '+detail,'','','']]
            t=table(['ID','Descrição','Status','Prioridade'], rows,[58,250,137,65])
        t.setStyle(TableStyle([('SPAN',(0,2),(-1,2)),('TOPPADDING',(0,0),(-1,-1),2),('BOTTOMPADDING',(0,0),(-1,-1),2)]))
        result.extend([t,Spacer(1,3)])
    return result

def diagram(kind):
    d=Drawing(425,315 if kind=='data' else 275)
    def box(x,y,w,ht,title,lines=()):
        d.add(Rect(x,y,w,ht,strokeColor=BLUE,fillColor=colors.HexColor('#edf5fa'),rx=3))
        d.add(String(x+w/2,y+ht-15,title,fontName='Arial-Bold',fontSize=9,textAnchor='middle'))
        for n,line in enumerate(lines):
            d.add(String(x+8,y+ht-30-n*12,line,fontName='Arial',fontSize=8))
    def arrow(x,y,x2,y2):
        d.add(Line(x,y,x2,y2,strokeColor=BLUE,strokeWidth=1.1))
        if y==y2:
            direction=1 if x2>x else -1
            points=[x2,y2,x2-5*direction,y2+3,x2-5*direction,y2-3]
        else:
            direction=1 if y2>y else -1
            points=[x2,y2,x2-3,y2-5*direction,x2+3,y2-5*direction]
        d.add(Polygon(points,fillColor=BLUE,strokeColor=BLUE))
    if kind=='architecture':
        box(0,215,200,55,'Portal do médico', ['Carteira, perfil e documentos'])
        box(225,215,200,55,'Portal do paciente',['Histórico, perfil e autorizações'])
        box(90,125,245,60,'Django + DRF',['JWT • views • serializers','Permissões • serviços • consultas ORM'])
        box(90,25,245,60,'PostgreSQL compartilhado',['Perfis • Record • Grant • Anexos'])
        arrow(100,215,165,185); arrow(325,215,265,185); arrow(210,125,210,85)
        d.add(String(212,197,'HTTP: JSON, multipart e PNG / JWT',fontName='Arial',fontSize=8,textAnchor='middle'))
        d.add(String(212,101,'Transações e validações de acesso',fontName='Arial',fontSize=8,textAnchor='middle'))
        d.add(String(212,5,'Sem banco ou schema exclusivo por médico ou paciente',fontName='Arial',fontSize=8,textAnchor='middle'))
