        box(65,195,140,40,'Solicitar acesso'); box(245,195,165,40,'Consultar / registrar')
        box(65,115,140,40,'Ler e decidir'); box(245,115,165,40,'Revogar novos acessos')
        box(65,35,140,40,'Validar perfil e Grant'); box(245,35,165,40,'Persistir e auditar')
