        box(65,70,300,65,'HUB MarIA',['Consultar histórico por autorização pessoal','Consultar registros por autoria • auditar operações'])
        arrow(60,180,130,135); arrow(210,180,210,135); arrow(365,180,300,135)
        d.add(String(212,30,'Recepção não possui acesso ao histórico clínico profissional.',fontName='Arial',fontSize=9,textAnchor='middle'))
