def institutional(c):
    for im,x,y,w,ht in background: c.drawImage(ImageReader(im),x,y,w,ht,mask='auto')
    c.setFillColor(colors.white); c.setFont('Arial',6.96)
    for j,line in enumerate(['Av. Universitária Km 3,5 - Cidade Universitária - Anápolis/GO, CEP 75083-515','Secretaria Setorial - Bloco I','Fone: (62) 3310 6658 | FAX: (62) 3310 6607']):
        c.drawString(326,39-j*8,line)

def build(path,pages,institution=True):
    c=canvas.Canvas(str(path),pagesize=(W,H))
    c.setTitle('MarIA - '+('Documento de Especificação - Fase 02' if institution else 'Histórico de Alterações - Fase 02' if 'historico' in path.name else 'Arquitetura - Fase 02'))
    c.setAuthor('Equipe MarIA')
    for n,items in enumerate(pages,1):
        if institution: institutional(c)
        if institution and n==1:
            c.setFillColor(colors.black);c.setFont('Arial',16);c.drawCentredString(W/2,399,'Documento de Especificação de Projeto Integrador')
            c.setFont('Arial-Bold',20);c.drawCentredString(W/2,352,'MarIA - Hub Médico Especializado')
            c.setFont('Arial',11);c.drawCentredString(W/2,324,'6º período - Fase 02 - 17/10/2026 | versão 1.2')
        else:
            top=H-(100 if institution else 65)
            y=top
            for item in items:
                if isinstance(item,Drawing):
                    ht=item.height; item.drawOn(c,85,y-ht); y-=ht+14; continue
                width=510 if getattr(item,'_wide',False) else 425
                x=42.5 if getattr(item,'_wide',False) else 85
                space_before=getattr(getattr(item,'style',None),'spaceBefore',0)
                space_after=getattr(getattr(item,'style',None),'spaceAfter',0)
                y-=space_before
                _,ht=item.wrap(width,y-78)
                if y-ht<78: raise ValueError(f'{path.name}: página {n} excedeu área útil ({y-ht:.1f}); {str(getattr(item,"text","tabela"))[:80]}')
                item.drawOn(c,x,y-ht); y-=ht+space_after
        if institution:
            c.setFillColor(colors.HexColor('#666666'));c.setFont('Arial',8);c.drawRightString(552,66,str(n))
        else:
            c.setFillColor(colors.grey);c.setFont('Arial',8);c.drawString(85,40,'MarIA | Fase 02 | 17/10/2026');c.drawRightString(510,40,str(n))
        c.showPage()
    c.save()

