NF=[
('RNF-001','Adequação Funcional','Parcial validado','MUST','Fluxo centrado no médico, com carteira e consulta por autorização; adaptação das demais telas permanece gradual.'),
('RNF-002','Integridade dos Registros','Implementado','MUST','Validação de entrada, chaves estrangeiras, restrições e transações. Não representa validação de acurácia clínica do conteúdo.'),
('RNF-003','Arquitetura Compartilhada','Implementado','MUST','PostgreSQL e schema compartilhados; controle por identidade, autoria e autorização. Substitui o requisito anterior de tenant por médico.'),
('RNF-004','Controle de Acesso por Perfis','Implementado','MUST','Perfil profissional ativo, titularidade do paciente e vínculos organizacionais são verificados no backend.'),
('RNF-005','Alta Disponibilidade','Não validado','MUST','A execução é local. Não há infraestrutura de produção nem medição de SLA de 99,5%.'),
('RNF-006','Persistência em PostgreSQL','Implementado','MUST','Banco relacional local em Docker; ORM e migrações preservam a evolução da estrutura e os dados existentes.'),
('RNF-007','Tratamento de Exceções','Parcial','MUST','API retorna erros semânticos e interface apresenta mensagens. Não há medição de taxa de falhas ou garantia quantitativa.'),
('RNF-008','Autenticação Segura','Parcial','MUST','JWT existente protege APIs. Revisão da chave, sessão e configuração de produção ainda pendente.'),
('RNF-009','Requisitos de Documentos Médicos','Planejado','MUST','Emissão certificada depende de avaliação específica e implementação futura; não há conformidade certificada nesta entrega.'),
('RNF-010','Isolamento por Regras de Acesso','Implementado','MUST','Serviços e consultas filtram autor e Grant. Não utiliza django-tenant-schemas, RLS ou schema individual.'),
('RNF-011','Prevenção de Exposição Indevida','Parcial','MUST','Sem diretório público; carteira e histórico limitados a 100 itens. Limitação de taxa e defesa contra extração exigem evolução.'),
('RNF-012','Privacidade e Proteção de Dados','Parcial','SHOULD','Autorização e revogação implementadas. Exclusão, anonimização, política de retenção, HTTPS e criptografia de repouso não foram validados.'),
('RNF-013','Usabilidade e Identidade Visual','Parcial validado','MUST','HTML, CSS nativo e JavaScript reaproveitam o frontend original. Não utiliza Tailwind nesta fase.'),
('RNF-014','Inteligibilidade de Fluxos','Implementado parcial','MUST','Portal diferencia solicitações, histórico compartilhado e autoria própria; diagramas refletem o fluxo atual.'),
('RNF-015','Acessibilidade Multiplataforma','Parcial','MUST','Portal web com rótulos, foco e mensagens. Não há aplicativo dedicado nem auditoria completa de acessibilidade.'),
('RNF-016','Independência de Sistema Operacional','Parcial','SHOULD','Interface web e dependências portáveis; ambiente validado localmente em Windows, sem ensaio completo em outros sistemas.'),
('RNF-017','Desempenho da API','Não medido','SHOULD','A meta anterior de 10 segundos não é declarada atingida. Testes de carga e métricas serão necessários.'),
('RNF-018','Governança da IA Assistiva','Planejado','MUST','ISO/IEC 42001 permanece referência para avaliação futura; não existe módulo de IA nem certificação comprovada.'),
('RNF-019','Integração e Entrega Contínuas','Não iniciado','SHOULD','Testes são executados localmente; não há pipeline de implantação contínua configurado nesta entrega.'),
('RNF-020','Backend Python','Implementado','MUST','Python, Django e Django REST Framework implementam as APIs e regras do protótipo.'),
('RNF-021','Tecnologia Frontend','Implementado','SHOULD','HTML semântico, CSS nativo, JavaScript com módulos e Fetch; templates servidos pelo Django na mesma origem da API.')]
