P[18]=[h('PARTE 04 - DESIGN, MODELAGEM, DADOS E SOLUÇÃO TECNOLÓGICA'),h('16 DESIGN DA SOLUÇÃO E EXPERIÊNCIA DO USUÁRIO'),sub('16.1 Fluxo de Navegação'),p('O médico autentica-se em /hub/login/ e acessa a carteira em /hub/. Pode solicitar autorização com o identificador recebido do paciente, consultar o histórico compartilhado, consultar seus próprios atendimentos e registrar um atendimento quando houver autorização pessoal vigente.'),p('O paciente autentica-se no mesmo portal e encontra seu identificador e as solicitações dirigidas a ele. Lê o termo, aceita, recusa ou revoga novos acessos. A interface do médico é atualizada pelo botão de acompanhamento; não há atualização automática entre abas no portal atual.'),sub('16.2 Protótipos do Sistema'),p('A identidade visual e os estilos das telas anteriores foram reaproveitados no portal integrado. As páginas legadas continuam como referência e não devem ser apresentadas como funcionalidades conectadas ao banco. O portal é servido pelo Django, não pelo Live Server isoladamente.'),h('17 GESTÃO DO PROJETO DE MODELAGEM DO SISTEMA'),sub('17.1 Organização do Projeto (Abordagem Ágil)'),p('A equipe utiliza divisão de tarefas e acompanhamento compartilhado. Carlos conduz a integração; Yasmin revisa arquitetura e frontend; Bárbara e Toin atualizam e validam a documentação, com participação de Carlos e Toin na validação do backend.'),sub('17.2 Modelagem e Diagramas do Sistema'),p('Os diagramas seguintes substituem os fluxos centrados em agenda, caixa e schemas individuais pelo funcionamento integrado da Fase 02.')]
