def render_contact(path):
    doc=pdfium.PdfDocument(path)
    folder=TMP/path.stem;folder.mkdir(exist_ok=True)
    for i,page in enumerate(doc):
        page.render(scale=1.25).to_pil().save(folder/f'pagina-{i+1:02}.png')
    for start in range(0,len(doc),9):
        sheet=Image.new('RGB',(900,1320),'#dddddd'); draw=ImageDraw.Draw(sheet)
        for pos,i in enumerate(range(start,min(start+9,len(doc)))):
            im=Image.open(folder/f'pagina-{i+1:02}.png'); im.thumbnail((290,410))
            x=(pos%3)*300;y=(pos//3)*440
            sheet.paste(im,(x,y+20));draw.text((x+5,y+3),f'Página {i+1}',fill='black')
        sheet.save(folder/f'contato-{start//9+1}.png')
    print(path, len(doc),'páginas')
    return len(doc)

counts={str(path):render_contact(path) for path in [spec_out,arch_out,changes_out]}
(TMP/'verificacao.json').write_text(json.dumps(counts,ensure_ascii=False,indent=2),encoding='utf-8')
